// ===== MINOR ARCANA BUILDER =====
function buildMinorArcana(): TarotCard[] {
  const suits = [
    {
      suit: "wands" as const, element: "fire" as const, name: "Wands", nameCn: "权杖",
      ranks: ["Ace", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Page", "Knight", "Queen", "King"],
      ranksCn: ["王牌", "二", "三", "四", "五", "六", "七", "八", "九", "十", "侍从", "骑士", "王后", "国王"],
      romans: ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII", "XIII", "XIV"],
      startId: 22,
      data: [
        { kwEn: ["Inspiration", "Potential", "Spark", "Creation"], kwZh: ["灵感", "潜能", "火花", "创造"],
          upEn: "Ace of Wands bursts with creative fire — a new venture, project, or passionate pursuit is born. The spark of inspiration has ignited; now channel this raw energy into focused action. This is pure potential in your hands.", upZh: "权杖王牌迸发着创造之火——一项新事业、新项目或热情的追求诞生了。灵感的火花已被点燃；现在将这股原始能量导入专注的行动。这是你手中的纯粹潜能。",
          revEn: "Creative block or false starts. The spark is there but you're not acting on it. A project stalls before it begins. Reignite your passion by reconnecting with your original vision.", revZh: "创意受阻或虚假的开端。火花在但你未行动。一个项目在开始之前就停滞了。重新连接你的原始愿景来重燃热情。" },
        { kwEn: ["Planning", "Vision", "Decision", "Future"], kwZh: ["计划", "远见", "决策", "未来"],
          upEn: "Two of Wands represents the moment of decision — you hold the world in your hands and must choose a direction. Long-term planning meets bold vision. Step beyond your comfort zone; the horizon calls.", upZh: "权杖二代表着决定的时刻——你将世界握在手中，必须选择方向。长期规划与大胆愿景相遇。走出你的舒适区；地平线在呼唤。",
          revEn: "Indecision or fear of the unknown paralyzes progress. You're over-planning without acting. The world waits while you hesitate. Choose — any direction is better than standing still.", revZh: "犹豫不决或对未知的恐惧使进展瘫痪。你在过度计划而没有行动。你犹豫时世界在等待。选择吧——任何方向都比原地不动好。" },
        { kwEn: ["Leadership", "Expansion", "Foresight", "Exploration"], kwZh: ["领导力", "扩张", "远见", "探索"],
          upEn: "Three of Wands shows your ships coming in — plans are bearing fruit, and horizons are expanding. Your foresight and preparation are paying off. Look beyond the immediate; the world is opening to you.", upZh: "权杖三展示了你的船队正在入港——计划正在结果，视野正在扩张。你的远见与准备正在回报。超越眼前去看；世界正向你敞开。",
          revEn: "Delayed results or limited vision. Plans hit unexpected obstacles. What you thought was a sure thing needs recalibration. Don't abandon ship — adjust the sails.", revZh: "结果延迟或视野受限。计划遭遇意外障碍。你以为确定的事情需要重新校准。别弃船——调整帆。" },
        { kwEn: ["Celebration", "Harmony", "Home", "Foundation"], kwZh: ["庆祝", "和谐", "家园", "根基"],
          upEn: "Four of Wands brings celebration and stability. A milestone is reached — wedding, promotion, housewarming. The foundation you've built is solid. Rejoice with those who helped you get here.", upZh: "权杖四带来了庆祝与稳定。一个里程碑达成了——婚礼、晋升、乔迁。你建立的根基是坚实的。与帮助过你的人一同欢庆。",
          revEn: "Delayed celebration or shaky foundations. A planned event falls through. The stability you thought you had needs reinforcing. Don't skip the groundwork.", revZh: "庆祝延迟或根基不稳。计划好的活动落空了。你以为拥有的稳定需要加固。别跳过基础工作。" },
        { kwEn: ["Conflict", "Competition", "Challenge", "Growth"], kwZh: ["冲突", "竞争", "挑战", "成长"],
          upEn: "Five of Wands depicts healthy competition — ideas clash, egos spar, but growth emerges from the friction. This is not destruction but creative tension. Engage fully; the conflict will sharpen you.", upZh: "权杖五描绘了健康的竞争——想法碰撞，自我较量，但成长从摩擦中产生。这不是破坏而是创造性的张力。充分参与；冲突会磨砺你。",
          revEn: "Conflict turns destructive — petty arguments, office politics, or inner turmoil. Avoidance makes it worse. Address the tension directly before it poisons the environment.", revZh: "冲突变得具有破坏性——琐碎的争吵、办公室政治或内心动荡。回避只会让事情更糟。在它毒害环境之前直接处理紧张局势。" },
        { kwEn: ["Victory", "Recognition", "Progress", "Triumph"], kwZh: ["胜利", "认可", "进展", "凯旋"],
          upEn: "Six of Wands rides in triumph — public recognition, a hard-won victory, your moment in the spotlight. Others see your achievements and celebrate you. Receive the praise graciously; you've earned it.", upZh: "权杖六凯旋而来——公众认可、一场来之不易的胜利、你的聚光灯时刻。他人看到了你的成就并为你庆祝。优雅地接受赞美；这是你应得的。",
          revEn: "Victory delayed or hollow. Recognition goes to someone else, or success feels empty. Check whether you're chasing external validation at the cost of inner fulfillment.", revZh: "胜利延迟或空洞。认可给了别人，或成功感觉空虚。检查你是否以牺牲内在满足为代价来追逐外在认可。" },
        { kwEn: ["Courage", "Defense", "Perseverance", "Stand"], kwZh: ["勇气", "防御", "坚持", "立场"],
          upEn: "Seven of Wands shows you standing your ground — outnumbered but not outmatched. Defend your position with courage. This is your hill to hold; your conviction is your strongest weapon.", upZh: "权杖七展示你坚守阵地——敌众我寡但势均力敌。用勇气捍卫你的立场。这是你要守住的阵地；你的信念就是你最强大的武器。",
          revEn: "Overwhelmed and defensive. You're fighting too many battles at once. Consider whether this hill is worth dying on. Strategic retreat is not defeat.", revZh: "不堪重负且防备心重。你同时在打太多场仗。考虑这座山头是否值得倾尽全力。战略性撤退不是失败。" },
        { kwEn: ["Speed", "Action", "Momentum", "Messages"], kwZh: ["速度", "行动", "势头", "消息"],
          upEn: "Eight of Wands flies with unstoppable momentum. Events accelerate — messages arrive, travel beckons, projects launch at lightning speed. Don't try to slow things down; ride this swift current.", upZh: "权杖八以不可阻挡的势头飞翔。事件加速——消息到达、旅行召唤、项目以闪电速度启航。不要试图减速；驾驭这股急流。",
          revEn: "Delays, miscommunication, or stalled momentum. Things that should be moving fast are stuck. Check for bottlenecks. The energy wants to flow — remove the obstruction.", revZh: "延迟、沟通不畅或势头停滞。本该快速推进的事情卡住了。检查瓶颈。能量想要流动——移除阻碍。" },
        { kwEn: ["Resilience", "Perseverance", "Last Stand", "Endurance"], kwZh: ["韧性", "毅力", "最后考验", "耐力"],
          upEn: "Nine of Wands shows you battle-weary but unbowed. You've been through the fire and you're still standing — one last push stands between you and victory. Your resilience is extraordinary. One. More. Step.", upZh: "权杖九展现你身经百战但未被击倒。你已穿越过烈火，仍然站着——最后的一推隔在你与胜利之间。你的韧性是非凡的。再。一。步。",
          revEn: "Burnout and exhaustion. You're so tired you're about to give up just before the finish line. Rest, but don't quit. The battle is almost won.", revZh: "倦怠与疲惫。你如此疲惫以至于快要放弃——终点线就在眼前。休息，但别放弃。战斗几乎已经赢了。" },
        { kwEn: ["Burden", "Responsibility", "Overwhelm", "Commitment"], kwZh: ["负担", "责任", "重压", "承诺"],
          upEn: "Ten of Wands carries a heavy load — too many responsibilities, too much on your plate. This is the cost of success. Delegate what you can; release what isn't yours to carry. The finish line is close.", upZh: "权杖十承载着重担——太多责任、太多事务。这就是成功的代价。尽你所能委派出去；释放那些不是你来承担的东西。终点线近了。",
          revEn: "Refusing to delegate or take on necessary responsibility — either extreme creates suffering. Learn to discern what's truly yours to carry. Put the load down before you break.", revZh: "拒绝分派任务或承担必要的责任——任一个极端都会造成痛苦。学会辨别什么是你真正来承担的。在你崩溃之前放下担子。" },
        { kwEn: ["Curiosity", "Exploration", "Enthusiasm", "New Idea"], kwZh: ["好奇", "探索", "热情", "新想法"],
          upEn: "Page of Wands brings youthful enthusiasm and a message of new beginnings. A creative spark, an exciting opportunity, or a passionate new interest arrives. Say yes to the adventure with wide-eyed wonder.", upZh: "权杖侍从带来了年轻的热情和关于新开始的消息。一道创意的火花、一个令人兴奋的机会或一种充满激情的新兴趣到来了。用睁大的好奇双眼答应这场冒险。",
          revEn: "Lack of direction or follow-through. Enthusiasm without commitment. A good idea abandoned before it has a chance. Find what truly lights you up before starting.", revZh: "缺乏方向或执行力。没有承诺的热情。一个好主意在有机会之前就被放弃了。在开始之前找到真正点燃你的东西。" },
        { kwEn: ["Adventure", "Charisma", "Bold Action", "Pursuit"], kwZh: ["冒险", "魅力", "大胆行动", "追求"],
          upEn: "Knight of Wands charges in with passion and charisma — a bold adventurer on a mission. This energy is magnetic, unstoppable, and a little reckless. Channel it toward a worthy quest; temper fire with wisdom.", upZh: "权杖骑士带着激情与魅力冲锋而来——一个执行任务的大胆冒险家。这股能量具有磁性、势不可挡且略带鲁莽。将它引向一项有价值的追求；用智慧调和烈火。",
          revEn: "Impulsive, restless, or scattered energy. Starting many things but finishing nothing. The fire burns out before it achieves anything. Slow down and commit.", revZh: "冲动、不安或分散的能量。开始很多事情但没有一件完成。火在成就任何事之前就熄灭了。慢下来，做出承诺。" },
        { kwEn: ["Confidence", "Warmth", "Leadership", "Radiance"], kwZh: ["自信", "温暖", "领导力", "光芒"],
          upEn: "Queen of Wands radiates warm, confident leadership. She creates with passion, leads with heart, and inspires everyone around her. This is sovereign feminine fire — creative, magnetic, and unapologetically bold.", upZh: "权杖王后散发着温暖、自信的领导力。她以激情创造，以心领导，激励着周围的每一个人。这是主权般的阴性之火——创造性、磁性且毫不抱歉地大胆。",
          revEn: "Jealousy, burnout, or using charisma to manipulate. The warmth has turned scorching. Reclaim your confidence through self-care, not external validation.", revZh: "嫉妒、倦怠或用魅力操控他人。温暖变成了灼烧。通过自我关怀而非外在认可来重获你的自信。" },
        { kwEn: ["Vision", "Entrepreneurship", "Mastery", "Direction"], kwZh: ["远见", "创业精神", "精通", "方向"],
          upEn: "King of Wands is the visionary leader — entrepreneurial, bold, and masterful. He sees the big picture and inspires others to build it. Take command of your vision with confidence and strategic fire.", upZh: "权杖国王是有远见的领导者——创业、大胆且精通。他能看到大局并激励他人去建造它。以自信和策略之火掌控你的愿景。",
          revEn: "Authoritarian leadership or grandiose plans without execution. Vision without follow-through. Check whether your ambition serves your ego or your purpose.", revZh: "威权式领导或缺乏执行力的宏大计划。没有后续行动的愿景。检查你的雄心是为自我还是为目标服务。" },
      ],
    },
    {
      suit: "cups" as const, element: "water" as const, name: "Cups", nameCn: "圣杯",
      ranks: ["Ace", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Page", "Knight", "Queen", "King"],
      ranksCn: ["王牌", "二", "三", "四", "五", "六", "七", "八", "九", "十", "侍从", "骑士", "王后", "国王"],
      romans: ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII", "XIII", "XIV"],
      startId: 36,
      data: [
        { kwEn: ["Love", "Emotion", "Intuition", "New Feeling"], kwZh: ["爱", "情感", "直觉", "新感受"],
          upEn: "Ace of Cups overflows with new love — romantic, platonic, or spiritual. Your heart opens, and emotional abundance pours in. This is the beginning of a deeply fulfilling emotional chapter. Let love flow.", upZh: "圣杯王牌满溢着新的爱——浪漫的、友谊的或灵性的。你的心打开了，情感的丰盈涌了进来。这是一个深度满足的情感篇章的开端。让爱流动。",
          revEn: "Emotional blockage or suppressed feelings. Love is available but you're not receiving it. Check for walls you've built around your heart.", revZh: "情感阻塞或被压抑的感受。爱就在那里但你无法接收。检视你围绕心筑起的墙。" },
        { kwEn: ["Partnership", "Union", "Harmony", "Connection"], kwZh: ["伴侣", "结合", "和谐", "连接"],
          upEn: "Two of Cups represents a beautiful emotional union — romantic partnership, deep friendship, or reconciliation. Two souls recognize each other. This is the card of mutual attraction and balanced emotional exchange.", upZh: "圣杯二代表着一段美丽的情感结合——浪漫伴侣、深刻友谊或和解。两个灵魂彼此认出了对方。这是相互吸引与平衡情感交换的牌。",
          revEn: "Imbalance in a relationship, broken trust, or one-sided affection. A connection is strained by unequal giving and receiving. Honest communication can restore the flow.", revZh: "关系中的不平衡、信任破裂或单方面的感情。一段连接因不平等的付出与接受而紧张。诚实的沟通可以恢复流动。" },
        { kwEn: ["Celebration", "Friendship", "Community", "Joy"], kwZh: ["庆祝", "友谊", "社群", "喜悦"],
          upEn: "Three of Cups is pure celebration — friendship, community, and shared joy. Gather with your soul tribe. Dance, laugh, and toast to life's sweetness. These bonds nourish your spirit.", upZh: "圣杯三是纯粹的庆祝——友谊、社群与共享的喜悦。与你的灵魂部落聚集。跳舞、大笑、为生活的甜美干杯。这些纽带滋养着你的精神。",
          revEn: "Social burnout, gossip, or exclusion. The celebration feels hollow, or you're on the outside looking in. Real friendship doesn't require performance.", revZh: "社交倦怠、闲言碎语或被排斥。庆祝感觉空洞，或者你是在外面往里看的人。真正的友谊不需要表演。" },
        { kwEn: ["Contemplation", "Dissatisfaction", "Apathy", "Re-evaluation"], kwZh: ["冥想", "不满足", "冷漠", "重估"],
          upEn: "Four of Cups shows you turning inward, dissatisfied with what's offered. A new opportunity sits unnoticed while you brood. This contemplation has value, but don't let apathy blind you to unexpected gifts.", upZh: "圣杯四展示你转向内心，对提供的东西感到不满。一个新机会在你不注意时坐在那里而你正在沉思。这种沉思是有价值的，但不要让冷漠蒙蔽了意外的礼物。",
          revEn: "Emerging from apathy. You're ready to engage with life again. A previously ignored opportunity gets a second look. The fog of discontent is lifting.", revZh: "从冷漠中浮现。你准备好再次投入生活了。一个之前被忽视的机会得到了第二次审视。不满的迷雾正在消散。" },
        { kwEn: ["Loss", "Grief", "Disappointment", "Perspective"], kwZh: ["失落", "悲伤", "失望", "视角"],
          upEn: "Five of Cups acknowledges grief and loss. Three cups have spilled, but two remain standing — there is still something to hold onto. Honor your pain; it's real and valid. Then, gently turn around and see what remains.", upZh: "圣杯五承认了悲伤与失去。三只杯子洒了，但两只仍然立着——仍有可以抓住的东西。尊重你的痛苦，它是真实且有效的。然后，温柔地转身，看看还有什么留下了。",
          revEn: "Recovery from loss. You're ready to move forward, having processed the grief. Focusing on what remains rather than what's lost. Hope returns.", revZh: "从失去中恢复。你准备好向前走了，已经处理了悲伤。专注于留下的而非失去的。希望回归。" },
        { kwEn: ["Nostalgia", "Memories", "Innocence", "Reunion"], kwZh: ["怀旧", "回忆", "纯真", "重逢"],
          upEn: "Six of Cups carries sweet nostalgia — childhood memories, past connections, and simple joys. Someone from your past may reappear. This is a card of innocent giving and receiving. Let the sweetness in.", upZh: "圣杯六承载着甜蜜的怀旧——童年记忆、过往连接与简单的快乐。某位故人可能重新出现。这是一张关于纯真给予与接受的牌。让甜蜜进来。",
          revEn: "Stuck in the past or idealizing what was. Living in memories prevents present joy. You can honor the past without living there. Come back to now.", revZh: "卡在过去或理想化过往。活在过去会阻碍当下的喜悦。你可以尊重过去而不必住在那里。回到现在。" },
        { kwEn: ["Fantasy", "Choices", "Dreams", "Illusion"], kwZh: ["幻想", "选择", "梦想", "幻觉"],
          upEn: "Seven of Cups presents a dazzling array of options — but not all are real. Dreams, fantasies, and illusions compete for your attention. Discernment is key. Which vision aligns with your soul's true path?", upZh: "圣杯七展示了令人眼花缭乱的选择——但并非都是真实的。梦想、幻想与幻觉在争夺你的注意力。辨别力是关键。哪个愿景与你灵魂的真正道路一致？",
          revEn: "Clarity emerges from the fog of options. You're done chasing illusions and ready to commit to a real path. Ground your dreams in practical action.", revZh: "清晰从选择的迷雾中浮现。你受够了追逐幻觉，准备好承诺一条真实的路。将你的梦想落实在实际行动中。" },
        { kwEn: ["Departure", "Walking Away", "Search", "Transformation"], kwZh: ["离开", "走开", "探索", "转变"],
          upEn: "Eight of Cups shows you walking away from what no longer fulfills you — a relationship, job, or situation that's emotionally drained. This departure is brave, not cowardly. You seek deeper meaning beyond the familiar.", upZh: "圣杯八展示你正在离开不再让你充实的事物——一段耗尽情感的关系、工作或处境。这种离开是勇敢的，而非懦弱。你在寻找超越熟悉的更深意义。",
          revEn: "Afraid to leave despite knowing you should. Clinging to comfort at the cost of growth. The call to move on will only get louder. Listen.", revZh: "害怕离开尽管知道应该走。以牺牲成长为代价紧抓舒适。离开的召唤只会越来越响。倾听。" },
        { kwEn: ["Wish Fulfilled", "Contentment", "Satisfaction", "Comfort"], kwZh: ["愿望实现", "满足", "满意", "舒适"],
          upEn: "Nine of Cups is the wish card — emotional fulfillment, deep satisfaction, and the sense that life is good. Your heart's desires are manifesting. Savor this contentment; you've created it through emotional honesty.", upZh: "圣杯九是愿望之牌——情感满足、深度满意，以及生活真好的感觉。你心中的渴望正在显现。品味这份满足；你通过情感诚实创造了它。",
          revEn: "The wish is achieved but feels hollow. Material comfort without emotional fulfillment. Check whether your wishes align with your true needs.", revZh: "愿望达成了但感觉空洞。没有情感满足的物质舒适。检查你的愿望是否与真正的需求一致。" },
        { kwEn: ["Family", "Harmony", "Emotional Fulfillment", "Legacy"], kwZh: ["家庭", "和谐", "情感圆满", "传承"],
          upEn: "Ten of Cups is emotional completion — harmonious family, lasting love, and a deep sense of belonging. The rainbow arcs over home and heart. This is the happy ending, the emotional homecoming.", upZh: "圣杯十是情感的完成——和谐的家庭、持久的爱与深深的归属感。彩虹跨越家园与心。这是幸福的结局，情感的回乡。",
          revEn: "Family discord or broken dreams of domestic bliss. The ideal of perfect happiness creates pressure. Real connection requires accepting imperfection.", revZh: "家庭不和或破裂的家庭幸福梦。完美幸福的理想制造了压力。真正的连接需要接纳不完美。" },
        { kwEn: ["Creativity", "Sensitivity", "New Emotion", "Intuition"], kwZh: ["创意", "敏感", "新情感", "直觉"],
          upEn: "Page of Cups brings a message of emotional awakening — a creative spark, a romantic overture, or an intuitive nudge. This gentle energy invites you to explore your feelings with childlike openness.", upZh: "圣杯侍从带来了情感觉醒的消息——一道创意火花、一个浪漫示意或一次直觉的轻推。这股温柔的能量邀请你以孩童般的开放心态探索你的情感。",
          revEn: "Emotional immaturity or creative block. Feelings are suppressed or expressed inappropriately. Let your inner child speak — but learn to channel emotions constructively.", revZh: "情感不成熟或创意受阻。感受被压抑或以不适切的方式表达。让你内在的小孩说话——但要学会建设性地疏导情感。" },
        { kwEn: ["Romance", "Proposal", "Charm", "Invitation"], kwZh: ["浪漫", "求婚", "魅力", "邀请"],
          upEn: "Knight of Cups rides in with romantic charm and heartfelt proposals — an offer of love, a creative invitation, or a peace offering. This energy is dreamy, idealistic, and deeply sincere. Follow your heart.", upZh: "圣杯骑士带着浪漫魅力与真诚提议而来——一份爱的提议、一个创意邀请或一个和平橄榄枝。这股能量梦幻、理想主义且深深真诚。跟随你的心。",
          revEn: "Unrealistic expectations, emotional manipulation, or broken promises. The charmer may not mean what they say. Check sincerity before investing your heart.", revZh: "不切实际的期望、情感操纵或破碎的承诺。迷人的表白者可能口是心非。在投入心灵之前检查真诚。" },
        { kwEn: ["Compassion", "Intuition", "Nurturing", "Empathy"], kwZh: ["慈悲", "直觉", "滋养", "共情"],
          upEn: "Queen of Cups is the emotional sovereign — deeply intuitive, compassionately nurturing, and emotionally wise. She feels everything deeply but isn't ruled by her feelings. Trust your emotional intelligence; it's your superpower.", upZh: "圣杯王后是情感的君主——深度直觉、慈悲滋养且情感智慧。她深切感受一切但不被感受支配。相信你的情商；它是你的超能力。",
          revEn: "Emotional enmeshment, martyrdom, or using sensitivity to manipulate. Feeling everything for everyone and losing yourself. Set emotional boundaries with love.", revZh: "情感纠缠、殉道或用敏感操纵他人。为每个人感受一切而失去了自己。带着爱设立情感边界。" },
        { kwEn: ["Emotional Mastery", "Diplomacy", "Wisdom", "Compassion"], kwZh: ["情感掌握", "外交", "智慧", "慈悲"],
          upEn: "King of Cups masters the emotional realm — calm in crisis, wise in counsel, diplomatic in conflict. He feels deeply but responds with measured grace. This is emotional maturity at its finest.", upZh: "圣杯国王掌握了情感领域——危机中冷静、建议中明智、冲突中外交。他深切感受但以克制的优雅回应。这是情感成熟度的最高境界。",
          revEn: "Emotional repression, moodiness, or using emotional intelligence to manipulate. The calm surface hides turbulent depths. Let feeling flow without controlling it.", revZh: "情感压抑、情绪化或用情商操纵他人。平静的表面下隐藏着汹涌的深处。让感受流动而不控制它。" },
      ],
    },
    {
      suit: "swords" as const, element: "air" as const, name: "Swords", nameCn: "宝剑",
      ranks: ["Ace", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Page", "Knight", "Queen", "King"],
      ranksCn: ["王牌", "二", "三", "四", "五", "六", "七", "八", "九", "十", "侍从", "骑士", "王后", "国王"],
      romans: ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII", "XIII", "XIV"],
      startId: 50,
      data: [
        { kwEn: ["Clarity", "Truth", "Breakthrough", "New Thought"], kwZh: ["清晰", "真理", "突破", "新思维"],
          upEn: "Ace of Swords cuts through confusion with razor-sharp clarity. A breakthrough idea, a moment of truth, or a decisive realization arrives. Mental clarity is your greatest asset now. Wield this sword with integrity.", upZh: "宝剑王牌以利刃般的清晰切穿困惑。一个突破性的想法、一个真相的时刻或一个决定性的领悟到来了。心智清晰是你此刻最大的资产。以正直挥舞这把剑。",
          revEn: "Confused thinking, misinformation, or a truth you're unwilling to face. The sword is double-edged — clarity can hurt. But the cut is necessary for healing.", revZh: "思维混乱、错误信息或一个你不愿面对的真实。剑是双刃的——清晰可能伤人。但这一刀对愈合是必要的。" },
        { kwEn: ["Stalemate", "Decision", "Balance", "Blindfold"], kwZh: ["僵局", "决策", "平衡", "蒙眼"],
          upEn: "Two of Swords represents a difficult choice made with eyes closed — a stalemate between heart and mind. Neither option feels perfect, but indecision is its own choice. Remove the blindfold; trust yourself to choose wisely.", upZh: "宝剑二代表着闭上双眼做的艰难选择——心与脑之间的僵局。没有哪个选项感觉完美，但犹豫不决本身就是一种选择。摘下蒙眼布；相信你能做出明智的选择。",
          revEn: "Information overload or forced decision. Paralysis breaks, but the choice feels rushed. You have more information than you think. Trust your logic.", revZh: "信息过载或被强迫的决定。瘫痪被打破了，但选择感觉仓促。你拥有的信息比你以为的多。相信你的逻辑。" },
        { kwEn: ["Heartbreak", "Sorrow", "Betrayal", "Release"], kwZh: ["心碎", "悲伤", "背叛", "释放"],
          upEn: "Three of Swords pierces the heart — grief, betrayal, or painful truth. This pain is real, and it demands to be felt. But the swords that pierce you also let the light in. Feel it fully so it can pass through you.", upZh: "宝剑三刺穿了心——悲伤、背叛或痛苦的真相。这种痛苦是真实的，它要求被感受到。但刺穿你的剑也同时让光透了进来。充分感受它，这样它才能穿过你。",
          revEn: "Healing from heartbreak. The pain is fading, and you're learning to trust again. Old wounds still ache but no longer define you. Forgiveness is becoming possible.", revZh: "从心碎中愈合。痛苦正在消退，你正在学习重新信任。旧伤仍然隐隐作痛但不再定义你。宽恕正在变得可能。" },
        { kwEn: ["Rest", "Recovery", "Meditation", "Retreat"], kwZh: ["休息", "恢复", "冥想", "撤退"],
          upEn: "Four of Swords calls for mental rest and recovery. Your mind has been overworked, overstimulated, overwrought. Retreat into stillness. This is not laziness — it's strategic restoration. The battle can wait.", upZh: "宝剑四呼唤心智的休息与恢复。你的头脑已经被过度劳累、过度刺激、过度紧张。退入静止。这不是懒惰——这是策略性的修复。战斗可以等待。",
          revEn: "Restlessness or inability to quiet the mind. You know you need rest but can't stop thinking. Forced return to activity before fully recovered. Prioritize recovery.", revZh: "不安或无法让头脑安静。你清楚需要休息但无法停止思考。在未完全恢复前被迫返回活动。优先恢复。" },
        { kwEn: ["Defeat", "Conflict", "Win-at-all-costs", "Hollow Victory"], kwZh: ["失败", "冲突", "不惜一切代价赢", "空洞胜利"],
          upEn: "Five of Swords warns of a Pyrrhic victory — you may win, but at what cost? Conflict leaves everyone diminished. Consider whether the battle is worth the casualties. Sometimes walking away is the truer victory.", upZh: "宝剑五警示着一场惨胜——你可能赢，但代价是什么？冲突让所有人都受损了。思考这场战斗是否值得付出伤亡。有时走开才是更真实的胜利。",
          revEn: "Reconciliation after conflict. Making amends, seeking peace, or letting go of the need to be right. The wounds begin to heal when pride steps aside.", revZh: "冲突后的和解。修复关系、寻求和平或放下需要是对的需求。当骄傲退让时伤口开始愈合。" },
        { kwEn: ["Transition", "Healing", "Moving On", "Journey"], kwZh: ["过渡", "治愈", "前行", "旅程"],
          upEn: "Six of Swords carries you away from troubled waters toward calmer shores. This is a necessary transition — leaving behind what no longer serves you. The journey may be bittersweet, but the destination promises peace.", upZh: "宝剑六带着你离开波涛汹涌的水域，驶向更平静的岸边。这是一场必要的过渡——放下不再服务你的事物。旅程可能苦甜参半，但目的地承诺着安宁。",
          revEn: "Resisting necessary change or return from a journey. You may feel stuck in troubled waters, unable to move forward. The boat is waiting — step in.", revZh: "抗拒必要的改变或从旅程中返回。你可能感到被困在波涛汹涌的水域中，无法前行。船在等待——上来吧。" },
        { kwEn: ["Deception", "Strategy", "Stealth", "Cunning"], kwZh: ["欺骗", "策略", "隐秘", "狡黠"],
          upEn: "Seven of Swords indicates strategy — perhaps too much of it. Someone may be acting deceptively, or you're taking shortcuts that compromise integrity. Be clever, not cunning. Honesty earns what stealth steals.", upZh: "宝剑七指向策略——也许有点过头了。有人可能在行骗，或者你在走捷径而损害了诚信。聪明但不狡猾。诚实赢得的东西，隐秘偷不走。",
          revEn: "Getting caught in deception or returning stolen goods. The truth comes out. A clean slate requires coming clean. The relief of honesty outweighs the comfort of secrecy.", revZh: "欺骗被抓到或归还赃物。真相被揭露了。一张白纸需要坦白。诚实的解脱胜过秘密的安逸。" },
        { kwEn: ["Restriction", "Trapped", "Powerlessness", "Self-limitation"], kwZh: ["限制", "被困", "无力", "自我设限"],
          upEn: "Eight of Swords shows a woman bound and blindfolded — but the bonds are loose, and swords don't fully encircle her. The prison is largely mental. Your perceived limitations are not as solid as they seem. You can free yourself.", upZh: "宝剑八展示了一个被绑住蒙眼的女人——但捆绑是松的，剑也没有完全围住她。这座监狱很大程度上是心理的。你感知到的限制并不像看上去那么坚固。你能够解放自己。",
          revEn: "Breaking free from mental prisons. Old limiting beliefs are being released. The blindfold comes off, and you see how free you always were.", revZh: "从心理监狱中挣脱。旧的限制信念正在被释放。蒙眼布被取下，你看到了自己一直都多么自由。" },
        { kwEn: ["Anxiety", "Nightmares", "Worry", "Overthinking"], kwZh: ["焦虑", "噩梦", "忧虑", "过度思考"],
          upEn: "Nine of Swords depicts the dark night of the soul — anxiety, insomnia, and mental torment. The worst scenarios play on repeat in your mind. But these are shadows, not prophecy. Reach out. You don't have to face this darkness alone.", upZh: "宝剑九描绘了灵魂的暗夜——焦虑、失眠与精神折磨。最糟糕的情景在你的脑海中重复播放。但这些是影子，不是预言。伸出手。你不必独自面对这份黑暗。",
          revEn: "The anxiety is beginning to lift. You're learning to challenge catastrophic thinking. Recovery is a process — celebrate every small victory over fear.", revZh: "焦虑开始消退了。你在学习挑战灾难化思维。恢复是一个过程——庆祝每一个战胜恐惧的小小胜利。" },
        { kwEn: ["Ending", "Rock Bottom", "Betrayal", "Finality"], kwZh: ["结束", "谷底", "背叛", "终结"],
          upEn: "Ten of Swords signals rock bottom — a painful ending, a devastating betrayal. It looks like the worst is here. But here's the gift: you can only go up from here. The dawn breaks even after the darkest night.", upZh: "宝剑十标志着谷底——一个痛苦的结束，一场毁灭性的背叛。看起来最糟的已经来了。但礼物在于：你只能从这里往上走。黎明即使在最黑的夜晚后也会到来。",
          revEn: "Recovery from rock bottom. The worst is truly over. Resilience is being forged from the ashes. You survived what you thought would destroy you.", revZh: "从谷底中恢复。最糟的真的过去了。韧性正在灰烬中被锻造出来。你从你以为会摧毁你的事情中幸存了下来。" },
        { kwEn: ["Curiosity", "New Ideas", "Vigilance", "Communication"], kwZh: ["好奇", "新想法", "警觉", "沟通"],
          upEn: "Page of Swords is intellectually curious — eager to learn, quick to question, and sharp of mind. A new idea or communication arrives. Stay curious, but temper your words with kindness. The truth serves best when served gently.", upZh: "宝剑侍从在智力上充满好奇——渴望学习、善于提问且头脑敏锐。一个新想法或一段沟通到来了。保持好奇，但用善意调和你的言语。真相在被温柔端上时效果最好。",
          revEn: "Gossip, cynicism, or using words as weapons. The sharp mind cuts indiscriminately. Think before you speak; not every truth needs to be spoken aloud.", revZh: "闲话、犬儒主义或用言语作武器。锋利的头脑胡乱切割。在说话之前思考；不是每一个真相都需要被说出来。" },
        { kwEn: ["Action", "Determination", "Charge", "Conviction"], kwZh: ["行动", "决心", "冲锋", "信念"],
          upEn: "Knight of Swords charges into battle with fierce determination and intellectual conviction. He moves fast, speaks directly, and cuts through obstacles. Channel this energy toward a worthy cause — but check for collateral damage.", upZh: "宝剑骑士以强烈的决心与智力信念冲入战斗。他行动迅速、言语直接且切穿障碍。将这股能量引向一项有价值的事业——但要检查附带损害。",
          revEn: "Reckless speech, impulsive decisions, or intellectual arrogance. Charging in without strategy causes chaos. Slow your mental horsepower before you crash.", revZh: "鲁莽的言语、冲动的决定或智力上的傲慢。没有策略地冲入会造成混乱。在你撞毁之前减慢你的脑力马力。" },
        { kwEn: ["Independence", "Clear Boundaries", "Perception", "Truth"], kwZh: ["独立", "清晰边界", "洞察力", "真相"],
          upEn: "Queen of Swords is the sovereign of clear thought and honest communication. She sees through illusions, sets firm boundaries, and speaks truth without cruelty. Her wisdom comes from experience. Think clearly; speak honestly; love freely.", upZh: "宝剑王后是清晰思维与诚实沟通的君主。她看穿幻觉、设立坚定边界且不带残酷地说出真相。她的智慧来自经历。清晰思考；诚实言说；自由去爱。",
          revEn: "Coldness, bitterness, or using intelligence to distance from emotion. The clarity has become cutting. Remember: truth without compassion is cruelty.", revZh: "冷漠、苦涩或用智慧疏远情感。清晰已经变成了刻薄。记住：没有慈悲的真理就是残忍。" },
        { kwEn: ["Authority", "Truth", "Intellect", "Justice"], kwZh: ["权威", "真理", "智慧", "公正"],
          upEn: "King of Swords rules with intellectual authority and moral clarity. He makes decisions based on truth and logic, not emotion. This is the energy of the wise judge — fair, analytical, and unwavering in principle.", upZh: "宝剑国王以智力权威与道德清晰进行统治。他基于真理和逻辑而非情感来做决定。这是智慧法官的能量——公正、善于分析且在原则上毫不动摇。",
          revEn: "Abuse of intellectual power, manipulation through words, or cold authoritarianism. The mind dominates at the expense of the heart. Justice without mercy is tyranny.", revZh: "滥用智力权力、通过言语操纵或冷酷的威权主义。头脑在牺牲心灵的情况下主导。没有慈悲的公正就是暴政。" },
      ],
    },
    {
      suit: "pentacles" as const, element: "earth" as const, name: "Pentacles", nameCn: "星币",
      ranks: ["Ace", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten", "Page", "Knight", "Queen", "King"],
      ranksCn: ["王牌", "二", "三", "四", "五", "六", "七", "八", "九", "十", "侍从", "骑士", "王后", "国王"],
      romans: ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX", "X", "XI", "XII", "XIII", "XIV"],
      startId: 64,
      data: [
        { kwEn: ["Opportunity", "Prosperity", "Manifestation", "New Venture"], kwZh: ["机遇", "繁荣", "显化", "新事业"],
          upEn: "Ace of Pentacles is the seed of material abundance — a new job offer, investment opportunity, or financial windfall. The universe hands you tangible possibility. Plant this seed with intention; it will grow into lasting prosperity.", upZh: "星币王牌是物质丰盛的种子——一份新的工作offer、投资机会或财务好运。宇宙递给了你切实的可能性。有意图地种下这颗种子；它将成长为持久的繁荣。",
          revEn: "Missed financial opportunity or poor investment. The seed is there but you're not planting it. Financial insecurity clouds your judgment. Reground in practical planning.", revZh: "错失的财务机会或糟糕的投资。种子在那里但你没有种下它。财务不安笼罩着你的判断。在实际规划中重新扎根。" },
        { kwEn: ["Balance", "Juggling", "Adaptability", "Multi-tasking"], kwZh: ["平衡", "兼顾", "适应力", "多任务"],
          upEn: "Two of Pentacles juggles life's demands with grace — balancing work and home, income and expenses, effort and rest. Adaptability is your strength. Stay flexible; the dance of priorities is ongoing, not a problem to be solved.", upZh: "星币二以优雅兼顾着生活的各种需求——平衡工作与家庭、收入与支出、努力与休息。适应力是你的优势。保持灵活；优先级的舞蹈是持续的，不是待解决的问题。",
          revEn: "Dropping balls — overextended and struggling to maintain balance. Financial disorganization creates stress. Simplify. You're juggling too many things that aren't all yours to carry.", revZh: "球掉了——过度扩张且难以维持平衡。财务混乱制造了压力。简化。你同时在兼顾太多并非都是你该承担的事。" },
        { kwEn: ["Teamwork", "Skill", "Craftsmanship", "Collaboration"], kwZh: ["团队合作", "技能", "工艺", "协作"],
          upEn: "Three of Pentacles celebrates skilled collaboration — a masterwork built by many hands. Your expertise is valued, and teamwork amplifies everyone's contribution. This is the card of quality, dedication, and shared achievement.", upZh: "星币三赞颂着有技巧的协作——由多双手共同打造的大师之作。你的专业被珍视，团队合作放大了每个人的贡献。这是质量、奉献与共享成就的牌。",
          revEn: "Poor teamwork, lack of quality, or undervalued contributions. Doing everything alone because collaboration feels harder. Great work requires great partners — invest in finding them.", revZh: "糟糕的团队合作、质量不足或贡献被低估。因为协作感觉更困难而独自承担一切。伟大的工作需要伟大的伙伴——投入精力去找他们。" },
        { kwEn: ["Security", "Control", "Conservation", "Stability"], kwZh: ["安全", "掌控", "保守", "稳定"],
          upEn: "Four of Pentacles holds tightly to security — financial stability, material comfort, and careful conservation. There's wisdom in saving and protecting. But check: are you holding on out of wisdom, or out of fear? Security is important; hoarding is not.", upZh: "星币四紧紧抓住安全——财务稳定、物质舒适与谨慎保存。储蓄和保护是有智慧的。但要检查：你的紧抓是出于智慧还是恐惧？安全很重要；囤积不是。",
          revEn: "Financial release — spending freely or letting go of material attachment. Generosity flows, or security is being lost through carelessness. Find the middle ground between hoarding and squandering.", revZh: "财务释放——自由消费或放下物质执着。慷慨在流动，或安全因疏忽在流失。在囤积与挥霍之间找到中间地带。" },
        { kwEn: ["Hardship", "Poverty", "Isolation", "Insecurity"], kwZh: ["困苦", "贫穷", "孤立", "不安"],
          upEn: "Five of Pentacles depicts material or spiritual hardship — financial struggle, illness, or feeling left out in the cold. But look closer: the church window glows warm with light. Help is available if you're willing to seek it. You are not as alone as you feel.", upZh: "星币五描绘了物质或灵性上的困苦——财务挣扎、病痛或感到被遗弃在寒冷中。但仔细看：教堂的窗户里有温暖的光。如果你愿意寻求，帮助是可得的。你没有像你感觉的那样孤单。",
          revEn: "Recovery from hardship. Financial or health struggles are easing. Finding community after isolation. The warmth you sought is finding its way to you.", revZh: "从困苦中恢复。财务或健康方面的挣扎正在缓解。在孤立之后找到了社群。你曾寻求的温暖正在找到通往你的路。" },
        { kwEn: ["Generosity", "Giving", "Receiving", "Balance"], kwZh: ["慷慨", "给予", "接收", "平衡"],
          upEn: "Six of Pentacles illustrates the beautiful cycle of giving and receiving. Resources flow where they are needed. Generosity is repaid in kind. Whether you're the giver or receiver now, honor the exchange. Abundance grows through circulation.", upZh: "星币六描绘了给予与接收的美好循环。资源流向需要之处。慷慨会以同样方式反馈。无论你此刻是给予者还是接收者，尊重这份交换。丰盛通过循环而增长。",
          revEn: "Imbalance in giving and receiving — charity with strings attached, or dependency on others' generosity. Check whether the flow of resources is truly equitable or masking a power dynamic.", revZh: "给予与接收不平衡——有附带条件的施舍或依赖他人的慷慨。检查资源的流动是真正公平还是掩藏着权力动态。" },
        { kwEn: ["Patience", "Assessment", "Growth", "Reflection"], kwZh: ["耐心", "评估", "成长", "反思"],
          upEn: "Seven of Pentacles shows you pausing to assess what you've grown. The harvest isn't quite ready — patience is still needed. But look how far you've come. This is the card of long-term investment and slow, steady growth. Trust the process.", upZh: "星币七展示你暂停下来评估你所培育的东西。收获还没有完全准备好——仍然需要耐心。但看看你已经走了多远。这是长期投资与缓慢稳定成长的牌。相信过程。",
          revEn: "Impatience with slow growth or poor return on investment. You've put in the work but the results are delayed. Don't abandon the crop just because it's not yet ripe.", revZh: "对缓慢成长缺乏耐心或投资回报不佳。你已经付出了努力但结果被延迟了。不要仅仅因为果实尚未成熟就放弃庄稼。" },
        { kwEn: ["Diligence", "Craftsmanship", "Skill-building", "Focus"], kwZh: ["勤奋", "手艺", "技能打磨", "专注"],
          upEn: "Eight of Pentacles is the master at work — focused, diligent, and absorbed in perfecting their craft. This is the card of deep practice and apprenticeship. Every repetition hones your skill. The master was once a beginner who never stopped showing up.", upZh: "星币八是工作中的大师——专注、勤奋且沉浸在完善手艺中。这是深度练习与学徒精神的牌。每一次重复都在磨砺你的技能。大师曾经也只是从未停止出现的新手。",
          revEn: "Monotonous labor, lack of passion, or cutting corners. Going through the motions without heart. Perfectionism without progress. Reconnect with why you started.", revZh: "单调的劳动、缺乏热情或偷工减料。没有心意地在走流程。没有进步的完美主义。重新连接你当初为什么开始。" },
        { kwEn: ["Independence", "Self-sufficiency", "Luxury", "Reward"], kwZh: ["独立", "自给自足", "享受", "回报"],
          upEn: "Nine of Pentacles basks in well-earned independence — financial self-sufficiency, refined taste, and the fruits of your labor. You've built this garden yourself. Enjoy the luxury of your own company and the beauty you've cultivated.", upZh: "星币九沐浴在当之无愧的独立中——财务自足、品味精致与劳动果实。这座花园是你自己打造的。享受你自己的陪伴和你所培育的美丽。",
          revEn: "Financial independence feels hollow without meaningful connection. Material comfort but emotional poverty. Find balance between self-sufficiency and allowing others in.", revZh: "财务独立如果没有有意义的连接会感觉空洞。物质舒适但情感贫乏。在自给自足与允许他人进入之间找到平衡。" },
        { kwEn: ["Wealth", "Legacy", "Inheritance", "Completion"], kwZh: ["财富", "传承", "遗产", "完成"],
          upEn: "Ten of Pentacles represents lasting wealth and generational legacy — not just money, but the richness of family, tradition, and enduring values. The long game has paid off. What you build now benefits those who come after you.", upZh: "星币十代表着持久的财富与世代传承——不止是金钱，而是家庭、传统与经久价值观的丰富。长远布局已经回报了。你现在建造的会让后来者受益。",
          revEn: "Family financial disputes, lost inheritance, or wealth without meaning. The material success feels empty because emotional bonds are broken. Wealth's true value lies in what it builds, not what it buys.", revZh: "家庭财务纠纷、失去遗产或没有意义的财富。物质成功感觉空虚，因为情感纽带断裂了。财富的真正价值在于它建造了什么，而不在于它购买了什么。" },
        { kwEn: ["Study", "Practicality", "New Skill", "Grounding"], kwZh: ["学习", "务实", "新技能", "扎根"],
          upEn: "Page of Pentacles is the eager student of the material world — practical, studious, and hungry to learn. A new course, job training, or financial opportunity arrives. Embrace beginner's mind; every expert started here.", upZh: "星币侍从是物质世界的好学学生——务实、勤奋且渴望学习。一门新课、工作培训或财务机会到来了。拥抱初学者的心态；每个专家都是从这里开始的。",
          revEn: "Lack of motivation, procrastination, or ignoring practical realities. The opportunity for growth is there but discipline is lacking. Ground your dreams in daily practice.", revZh: "缺乏动力、拖延或忽视实际现实。成长的机会在那里但自律不足。在日常实践中扎根你的梦想。" },
        { kwEn: ["Reliability", "Efficiency", "Responsibility", "Duty"], kwZh: ["可靠", "效率", "责任", "本分"],
          upEn: "Knight of Pentacles moves with steady, unshakeable reliability. He's not flashy, but he gets things done. This energy is methodical, patient, and utterly dependable. Progress is slow but certain — and that's its strength.", upZh: "星币骑士以稳健、不可动摇的可靠性前行。他不华丽，但他把事情做成。这股能量是有条不紊的、耐心的且完全可靠的。进展缓慢但确定——这正是它的力量。",
          revEn: "Stagnation, boredom, or grinding without purpose. Reliability has become rigidity. The routine that once grounded you now suffocates you. Shake things up gently.", revZh: "停滞、无聊或没有目的地苦干。可靠性已经成为了死板。曾经让你扎根的惯例现在正在窒息你。温和地做出改变。" },
        { kwEn: ["Nurturing", "Practical Care", "Abundance", "Warmth"], kwZh: ["滋养", "实际关怀", "丰盛", "温暖"],
          upEn: "Queen of Pentacles is the embodiment of practical nurturing — she creates comfort, tends to the physical world, and makes everyone feel at home. Her wealth is measured in warmth, not just currency. Nurture your body, your space, and your people.", upZh: "星币王后是实际滋养的化身——她创造舒适，照料物质世界，让每个人都感觉如家。她的财富以温暖衡量，而非仅是货币。滋养你的身体、你的空间和你的家人。",
          revEn: "Neglecting self-care, financial codependency, or using material gifts to control. The nurturer has forgotten to nurture herself. Fill your own cup first.", revZh: "忽视自我关怀、财务共生依赖或用物质礼物进行控制。滋养者忘记了滋养自己。先填满你自己的杯子。" },
        { kwEn: ["Success", "Wealth", "Mastery", "Achievement"], kwZh: ["成功", "财富", "精通", "成就"],
          upEn: "King of Pentacles sits on the throne of material mastery — successful, prosperous, and deeply grounded. He has built lasting wealth through patience and practical wisdom. This is the energy of the generous provider and the wise steward.", upZh: "星币国王坐于物质掌握的王座上——成功、繁荣且深度扎根。他通过耐心与实际智慧建立了持久的财富。这是慷慨的供养者与智慧管家的能量。",
          revEn: "Greed, materialism, or using wealth for control. Success without soul. The fortune was gained but at what cost? Wealth's true purpose is to serve life, not define it.", revZh: "贪婪、物质主义或用财富进行控制。没有灵魂的成功。财富是获得了但代价是什么？财富的真正目的是服务生活，而非定义它。" },
      ],
    },
  ];

  const cards: TarotCard[] = [];
  for (const s of suits) {
    for (let i = 0; i < s.ranks.length; i++) {
      const d = s.data[i];
      cards.push({
        id: s.startId + i,
        name: `${s.ranks[i]} of ${s.name}`,
        nameCn: `${s.nameCn}${s.ranksCn[i]}`,
        roman: s.romans[i],
        suit: s.suit,
        element: s.element,
        image: `/tarot/${s.startId + i}.jpg`,
        keywordsEn: d.kwEn,
        keywordsZh: d.kwZh,
        meaningUprightEn: d.upEn,
        meaningUprightZh: d.upZh,
        meaningReversedEn: d.revEn,
        meaningReversedZh: d.revZh,
        scenes: {
          general: { en: d.upEn, zh: d.upZh },
          love: { en: "", zh: "" },
          career: { en: "", zh: "" },
          idol: { en: "", zh: "" },
        },
      });
    }
  }
  return cards;
}

export const TAROT_CARDS: TarotCard[] = [...MAJOR_ARCANA, ...buildMinorArcana()];

export function getCardById(id: number): TarotCard | undefined {
  return TAROT_CARDS.find(c => c.id === id);
}

export function drawRandomCards(count: number): TarotCard[] {
  const shuffled = [...TAROT_CARDS].sort(() => Math.random() - 0.5);
  return shuffled.slice(0, count);
}

